  void Click(float x,float y){foreach(bool down in new[]{false,true,false}){var raw=new RawInputSnapshot();if(down)raw.MouseButtonsDown.Add(MouseButton.Left);typeof(Input).GetMethod("UpdatePortable",BindingFlags.Static|BindingFlags.NonPublic)!.Invoke(null,[raw,true]);Input.SetGameViewPointer(new Vector2(x/1280,y/720),new(1280,720),true);typeof(MiningResearchStation3D).GetMethod("TickShopInput",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(shop,null);}}
  int before=op.Credits;Click(716,580);Check(op.Credits==before,"selecting a cargo card does not purchase it");int capacity=op.CargoCapacity,cost=op.CargoUpgradeCost;Click(1120,519);Check(op.CargoCapacity>capacity&&op.Credits==before-cost,"cargo purchase button buys exactly once");before=op.Credits;Click(1110,190);Check(op.Credits==before,"active drone button never charges again");host.UnloadScene();
